theme.css:
/* theme: Last Hurrah | The day's calm is deceptive — markets simmer while midterms barrels toward a verdict, a quiet pre-storm Sunday edition */
/* layout: hero=centered; political-news=timeline/stack; financial-news=numbered/grid-2; entertainment-news=tile/masonry; music-releases=plain/stack; stock-analysis=stat/grid-3; outlook=outline/stack */

.diary-page {
  --paper: #f2efe8;
  --paper-alt: #e7e2d8;
  --ink: #1f1d1a;
  --ink-soft: #4a443c;
  --muted: #6b6152;
  --accent: #7a5a2e;
  --accent-ink: #fdfcf9;
  --rule: #d4cdbe;
  --font-display: var(--ff-instrument), serif;
  --font-body: var(--ff-newsreader), Georgia, serif;
  --font-ui: var(--ff-inter), system-ui, sans-serif;
  background: var(--paper);
  color: var(--ink-soft);
}

.diary-page .diary-hero {
  background: var(--paper-alt);
  border-bottom: 2px solid var(--rule);
}

.diary-page .diary-hero-inner {
  padding-top: 1rem;
}

.diary-page .diary-kicker {
  letter-spacing: 0.28em;
  font-size: 0.7rem;
  color: var(--muted);
}

.diary-page .diary-title {
  font-size: clamp(2.2rem, 5.5vw, 4.2rem);
  font-weight: 400;
  line-height: 1.15;
  letter-spacing: -0.02em;
  text-transform: none;
}

.diary-page .diary-summary {
  font-size: 1.1rem;
  line-height: 1.6;
  color: var(--ink-soft);
}

.diary-page .diary-theme-note {
  text-align: center;
  font-style: italic;
}

.diary-page .diary-theme-name {
  background: var(--accent);
  color: var(--accent-ink);
  font-family: var(--font-ui);
  font-style: normal;
  letter-spacing: 0.08em;
}

@media (prefers-color-scheme: dark) {
  .diary-page {
    --paper: #1b1915;
    --paper-alt: #242019;
    --ink: #f2efe6;
    --ink-soft: #c9c2b0;
    --muted: #9a9180;
    --accent: #c9a054;
    --accent-ink: #1b1915;
    --rule: #3a352c;
  }
}

.diary-page .diary-toc {
  background: var(--paper-alt);
  border-bottom: 1px solid var(--accent);
}

.diary-page .diary-toc-list {
  gap: 0;
  border-top: 1px solid var(--rule);
}

.diary-page .diary-toc-link {
  color: var(--muted);
}

.diary-page .diary-toc-link.is-active {
  color: var(--ink);
}

.diary-page .diary-section {
  border-top: 1px solid var(--rule);
}

.diary-page .diary-section-head {
  border-bottom: 1px solid var(--rule);
  padding-bottom: 0.5rem;
}

.diary-page .diary-section-title {
  font-size: clamp(1.7rem, 3vw, 2.3rem);
  font-weight: 400;
  letter-spacing: -0.01em;
  color: var(--ink);
}

.diary-page .diary-section-number {
  font-size: 0.7rem;
  color: var(--accent);
}

/* Political News: timeline/stack — a slow countdown, not urgency */
.diary-page [data-section="political-news"] .diary-card--timeline .diary-card-inner {
  padding-left: 2.5rem;
}

.diary-page [data-section="political-news"] .diary-card--timeline .diary-card-inner::before {
  left: 0.6rem;
  width: 3px;
  background: var(--accent);
}

.diary-page [data-section="political-news"] .diary-card--timeline .diary-card-inner::after {
  left: 0;
  width: 1rem;
  height: 1rem;
  border-radius: 50%;
  background: var(--accent-ink);
  border: 3px solid var(--accent);
  box-shadow: 0 0 0 2px var(--paper);
}

.diary-page [data-section="political-news"] .diary-card--timeline .diary-card-title {
  font-size: 1.25rem;
  line-height: 1.4;
  color: var(--ink-soft);
}

.diary-page [data-section="political-news"] .diary-card--timeline .diary-card-body {
  font-size: 1.1rem;
  color: var(--ink-soft);
}

.diary-page [data-section="political-news"] .diary-stories {
  max-width: 34rem;
  gap: 1.75rem;
}

.diary-page [data-section="political-news"] .diary-card-thread {
  background: var(--accent);
  color: var(--accent-ink);
  border: 1px solid var(--accent);
}

/* Financial News: numbered/grid-2 — ledgers of gains and losses */
.diary-page [data-section="financial-news"] .diary-card--numbered .diary-card-inner {
  gap: 0.5rem;
}

.diary-page [data-section="financial-news"] .diary-card--numbered .diary-card-index {
  font-size: 2.2rem;
  font-weight: 400;
  color: var(--muted);
}

.diary-page [data-section="financial-news"] .diary-card--numbered .diary-card-title {
  font-size: 1.1rem;
  font-weight: 600;
  color: var(--ink);
}

.diary-page [data-section="financial-news"] .diary-card--numbered .diary-card-body {
  font-size: 0.95rem;
  line-height: 1.65;
  color: var(--ink-soft);
}

.diary-page [data-section="financial-news"] .diary-card--numbered .diary-card-inner::after {
  content: "";
  display: block;
  border-top: 1px solid var(--rule);
  margin-top: 0.25rem;
}

/* Entertainment News: tile/masonry — light, airy, varied */
.diary-page [data-section="entertainment-news"] .diary-card--tile .diary-card-inner {
  padding: 1rem 1.25rem;
  background: var(--paper-alt);
  border: 1px solid transparent;
}

.diary-page [data-section="entertainment-news"] .diary-card--tile .diary-card-title {
  font-size: 1rem;
  font-weight: 600;
  color: var(--ink);
  letter-spacing: 0.01em;
}

.diary-page [data-section="entertainment-news"] .diary-card--tile .diary-card-body {
  font-size: 0.9rem;
  line-height: 1.6;
  color: var(--ink-soft);
}

.diary-page [data-section="entertainment-news"] .diary-stories {
  column-gap: 1.25rem;
  gap: 1.25rem;
}

/* Music Releases: plain/stack — a quiet Sunday reading list */
.diary-page [data-section="music-releases"] .diary-card--plain .diary-card-inner {
  gap: 0;
}

.diary-page [data-section="music-releases"] .diary-card--plain .diary-card-title {
  font-size: 1.1rem;
  font-weight: 600;
  color: var(--ink);
}

.diary-page [data-section="music-releases"] .diary-card--plain .diary-card-body {
  font-size: 1rem;
  line-height: 1.6;
  color: var(--ink-soft);
}

/* Stock Analysis: stat/grid-3 — the market's pulse, numbers front and center */
.diary-page [data-section="stock-analysis"] .diary-card--stat .diary-card-inner {
  padding-top: 0.75rem;
  border-top: 2px solid var(--accent);
}

.diary-page [data-section="stock-analysis"] .diary-card--stat .diary-card-figure {
  font-size: clamp(2rem, 10cqi, 3rem);
  color: var(--accent);
  font-family: var(--font-display);
}

.diary-page [data-section="stock-analysis"] .diary-card--stat .diary-card-title {
  font-size: 1.05rem;
  font-weight: 600;
  color: var(--ink-soft);
}

.diary-page [data-section="stock-analysis"] .diary-card--stat .diary-card-body {
  font-size: 0.9rem;
  line-height: 1.6;
  color: var(--muted);
}

.diary-page [data-section="stock-analysis"] .diary-markets-wrap {
  margin-bottom: 1.5rem;
}

.diary-page [data-section="stock-analysis"] .diary-markets-label {
  letter-spacing: 0.2em;
  color: var(--muted);
}

.diary-page [data-section="stock-analysis"] .diary-spark {
  background: var(--paper-alt);
  border-color: var(--rule);
}

.diary-page [data-section="stock-analysis"] .diary-spark.is-up {
  color: var(--accent);
}

.diary-page [data-section="stock-analysis"] .diary-spark.is-down {
  color: var(--ink-soft);
}

/* Outlook: outline/stack — a list of things to watch */
.diary-page [data-section="outlook"] .diary-card--outline .diary-card-inner {
  padding: 1.25rem 1.5rem;
  border: 1px solid var(--accent);
  border-radius: 0;
}

.diary-page [data-section="outlook"] .diary-card--outline .diary-card-title {
  font-size: 1.15rem;
  font-weight: 600;
  color: var(--ink);
}

.diary-page [data-section="outlook"] .diary-card--outline .diary-card-body {
  font-size: 1rem;
  line-height: 1.65;
  color: var(--ink-soft);
}

.diary-page [data-section="outlook"] .diary-stories {
  max-width: 40rem;
  gap: 1rem;
}

.diary-page .diary-prose a {
  color: var(--accent);
  border-bottom: 1px solid color-mix(in srgb, var(--accent) 60%, transparent);
}

.diary-page .diary-card-lede {
  border-left: 2px solid var(--accent);
  color: var(--ink-soft);
}

.diary-page .diary-footer {
  border-top: 1px solid var(--accent);
}

.diary-page .diary-footer a {
  color: var(--ink-soft);
}

.diary-page .diary-footer a:hover {
  color: var(--accent);
}

@media (min-width: 1024px) {
  .diary-page .diary-toc {
    background: none;
    border-bottom: 0;
  }
}
